80	@RestController
81	@CrossOrigin(exposedHeaders = "errors, content-type")
82	@RequestMapping("/api")
83	public class OwnerRestControllerV1 implements OwnersApi {
84	
85	    /**
86	     * Dedicated audit logger. A successful owner create emits here, independently of the application
87	     * log: first a human-readable line carrying the new owner's id, customer code, registration date
88	     * and membership level, then the immutable structured {@code OWNER_CREATED} event (see
89	     * {@link OwnerCreatedEvent}) as a compact JSON object.
90	     */
91	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
92	
93	    /**
94	     * Process-wide sequence backing the {@code seq} of the structured {@code OWNER_CREATED} event. It
95	     * is incremented once per successful create so each emitted event carries a strictly larger,
96	     * monotonically increasing sequence number than the one before it.
97	     */
98	    private static final AtomicInteger AUDIT_SEQUENCE = new AtomicInteger();
99	
100	    private final ClinicService clinicService;
101	
102	    private final OwnerMapper ownerMapper;
103	
104	    private final PetMapper petMapper;
105	
106	    private final VisitMapper visitMapper;
107	
108	    /**
109	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
110	     * and a domain containing at least one dot, with no whitespace in any segment.
111	     */
112	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
113	
114	    /**
115	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
116	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
117	     * {@code '@'}) is rejected with a 400 Bad Request.
118	     */
119	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
120	        "mailinator.com",
121	        "tempmail.com",
122	        "guerrillamail.com");
123	
124	    /**
125	     * Required national-number length per E.164 country code. A normalized telephone whose country
126	     * code appears here must carry exactly this many national digits after the code; Australia
127	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
128	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
129	     */
130	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
131	
132	    /**
133	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
134	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
135	     */
136	    private static final int MAX_OWNERS_PER_CITY = 50;
137	
138	    /**
139	     * Maximum number of owners that may be registered on a single day (by registration date). A create
140	     * attempted once this many owners already carry today's registration date is rejected with a
141	     * 429 Too Many Requests.
142	     */
143	    private static final int MAX_OWNERS_PER_DAY = 100;
144	
145	    /**
146	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
147	     * owners already carry the new owner's registration date, the created owner is flagged
148	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
149	     */
150	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
151	
152	    /**
153	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
154	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
155	     */
156	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
157	        "ST", "STREET",
158	        "RD", "ROAD",
159	        "AVE", "AVENUE");
160	
161	    /**
162	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
163	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
164	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
165	     * 4-digit postcode.
166	     */
167	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
168	        "NSW", new int[] {2000, 2099},
169	        "VIC", new int[] {3000, 3099},
170	        "QLD", new int[] {4000, 4099});
171	
172	    /**
173	     * Name of the request header that carries the client-supplied idempotency key for an owner create.
174	     * When a create repeats with a key already seen, the originally created owner is returned with
175	     * {@code 200 OK} instead of a second owner being created.
176	     */
177	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
178	
179	    /**
180	     * Remembers, per idempotency key, the id of the owner created by the first request that carried that
181	     * key, so a later create repeating the same key can return the original owner instead of creating a
182	     * duplicate. The key space is the client-supplied {@code Idempotency-Key} header value.
183	     */
184	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
185	
186	    public OwnerRestControllerV1(ClinicService clinicService,
187	                                 OwnerMapper ownerMapper,
188	                                 PetMapper petMapper,
189	                                 VisitMapper visitMapper) {
190	        this.clinicService = clinicService;
191	        this.ownerMapper = ownerMapper;
192	        this.petMapper = petMapper;
193	        this.visitMapper = visitMapper;
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
199	        Collection<Owner> owners;
200	        if (lastName != null) {
201	            owners = this.clinicService.findOwnerByLastName(lastName);
202	        } else {
203	            owners = this.clinicService.findAllOwners();
204	        }
205	        if (owners.isEmpty()) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
209	    }
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
214	        Owner owner = this.clinicService.findOwnerById(ownerId);
215	        if (owner == null) {
216	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	        }
218	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
224	        String idempotencyKey = currentIdempotencyKey();
225	        OwnerDto replayed = replayIfSeen(idempotencyKey);
226	        if (replayed != null) {
227	            return new ResponseEntity<>(replayed, HttpStatus.OK);
228	        }
229	        validateRequiredFields(ownerFieldsDto);
230	        HttpHeaders headers = new HttpHeaders();
231	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
232	        rejectFutureRegistrationDate(owner.getRegistrationDate());
233	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
234	        owner.setRegistrationDate(registrationDate);
235	        requireDailyCapacity(registrationDate);
236	        requireCityHasCapacity(owner.getCity());
237	        validatePostcode(owner);
238	        applyAddress(owner, ownerFieldsDto);
239	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
240	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
241	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
242	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
243	        requireUniqueIdentity(owner);
244	        flagPossibleDuplicate(owner, declaredHouseholdMember);
245	        owner.setCustomerCode(deduplicateCustomerCode(owner.buildCustomerCode()));
246	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
247	        stampHouseholdSize(owner);
248	        capMembershipLevelToHousehold(owner);
249	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
250	        this.clinicService.saveOwner(owner);
251	        rememberCreate(idempotencyKey, owner);
252	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
253	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
254	            owner.getMembershipNumber());
255	        emitOwnerCreatedEvent(owner);
256	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
257	        headers.setLocation(UriComponentsBuilder.newInstance()
258	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
259	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
260	    }
261	
262	    /**
263	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@link #AUDIT} logger as a
264	     * compact JSON object, alongside the human-readable audit line. The event's {@code seq} is drawn
265	     * from the process-wide {@link #AUDIT_SEQUENCE}, so it strictly increases across creates, and it
266	     * carries both the owner's id and its current primary identifier via
267	     * {@link #primaryIdentifier(Owner)}.
268	     *
269	     * @param owner the owner that was just created and saved
270	     */
271	    private void emitOwnerCreatedEvent(Owner owner) {
272	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQUENCE.incrementAndGet(),
273	            owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel());
274	        AUDIT.info(event.toJson());
275	    }
276	
277	    /**
278	     * The owner's current primary identifier, the single value the structured {@code OWNER_CREATED}
279	     * event carries to identify the owner. Today that is the owner's {@link Owner#getCustomerCode()
280	     * customer code}; when the customer code is later unified into the member id, this becomes the
281	     * sole place to switch so the event carries the member id instead.
282	     *
283	     * @param owner the owner that was just created
284	     * @return the owner's current primary identifier
285	     */
286	    private String primaryIdentifier(Owner owner) {
287	        return owner.getCustomerCode();
288	    }
289	
290	    /**
291	     * The immutable structured event emitted on a successful owner create. {@code seq} is the
292	     * process-wide monotonically increasing sequence across creates; {@code ownerId} is the new
293	     * owner's id; {@code customerCode} carries the owner's current primary identifier (today the
294	     * customer code, whatever replaces it later); {@code membershipLevel} is the owner's membership
295	     * level. It serializes to a compact JSON object whose {@code event} is always
296	     * {@value #EVENT_TYPE}.
297	     *
298	     * @param seq the monotonically increasing create sequence number
299	     * @param ownerId the created owner's id
300	     * @param customerCode the owner's current primary identifier
301	     * @param membershipLevel the owner's membership level
302	     */
303	    private record OwnerCreatedEvent(int seq, Integer ownerId, String customerCode, Integer membershipLevel) {
304	
305	        /** The fixed {@code event} discriminator carried by every emitted event. */
306	        private static final String EVENT_TYPE = "OWNER_CREATED";
307	
308	        /** Shared, thread-safe mapper used only to serialize the event to its JSON form. */
309	        private static final ObjectMapper MAPPER = JsonMapper.builder().build();
310	
311	        /**
312	         * Serializes this event to its compact JSON form
313	         * {@code {seq, ownerId, customerCode, membershipLevel, event}}, with the fields in that order.
314	         *
315	         * @return the event as a JSON object string
316	         */
317	        private String toJson() {
318	            Map<String, Object> fields = new LinkedHashMap<>();
319	            fields.put("seq", this.seq);
320	            fields.put("ownerId", this.ownerId);
321	            fields.put("customerCode", this.customerCode);
322	            fields.put("membershipLevel", this.membershipLevel);
323	            fields.put("event", EVENT_TYPE);
324	            return MAPPER.writeValueAsString(fields);
325	        }
326	    }
327	
328	    /**
329	     * Reads the client-supplied idempotency key from the current request's {@code Idempotency-Key}
330	     * header. Returns {@code null} when the header is absent or blank (the create is not idempotent),
331	     * or when no servlet request is bound to the current thread.
332	     *
333	     * <p>The header is read from the bound request rather than taken as a {@code @RequestHeader} method
334	     * parameter because {@code addOwner}'s signature is fixed by the generated {@link OwnersApi}
335	     * interface and cannot carry an extra parameter.
336	     *
337	     * @return the trimmed idempotency key, or {@code null} when none was supplied
338	     */
339	    private String currentIdempotencyKey() {
340	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
341	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
342	            if (StringUtils.hasText(key)) {
343	                return key.trim();
344	            }
345	        }
346	        return null;
347	    }
348	
349	    /**
350	     * Returns the owner originally created under the given idempotency key, so a create repeating a
351	     * key already seen replays the first result instead of creating a duplicate. Yields {@code null}
352	     * when there is no key, the key has not been seen, or the remembered owner no longer exists (in
353	     * which case the create proceeds normally).
354	     *
355	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
356	     * @return the originally created owner as a DTO, or {@code null} when there is nothing to replay
357	     */
358	    private OwnerDto replayIfSeen(String idempotencyKey) {
359	        if (idempotencyKey == null) {
360	            return null;
361	        }
362	        Integer existingId = idempotentCreates.get(idempotencyKey);
363	        if (existingId == null) {
364	            return null;
365	        }
366	        Owner existing = this.clinicService.findOwnerById(existingId);
367	        return existing == null ? null : ownerMapper.toOwnerDto(existing);
368	    }
369	
370	    /**
371	     * Remembers the id of a just-created owner against the idempotency key that produced it, so a later
372	     * create repeating the same key can be replayed by {@link #replayIfSeen}. A {@code null} key (the
373	     * create was not idempotent) is ignored.
374	     *
375	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
376	     * @param owner the owner that was just created and saved
377	     */
378	    private void rememberCreate(String idempotencyKey, Owner owner) {
379	        if (idempotencyKey != null) {
380	            idempotentCreates.put(idempotencyKey, owner.getId());
381	        }
382	    }
383	
384	    /**
385	     * Rejects a create whose supplied registration date is later than the server's current date. A
386	     * registration may be back-dated but never post-dated, so a future date is treated as a client
387	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
388	     * server date.
389	     *
390	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
391	     *     client omitted it
392	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
393	     */
394	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
395	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
396	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
397	        }
398	    }
399	
400	    /**
401	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
402	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
403	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
404	     * existed prior to this create.
405	     *
406	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
407	     *     a business day
408	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
409	     *     registered on that business day
410	     */
411	    private void requireDailyCapacity(LocalDate registrationDate) {
412	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
413	            throw new DailyOwnerLimitException(registrationDate);
414	        }
415	    }
416	
417	    /**
418	     * Counts the existing owners whose registration date equals the given business-day date. This is
419	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
420	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
421	     * the bulk-signup warning.
422	     *
423	     * @param registrationDate the effective business-day registration date to count against
424	     * @return the number of pre-existing owners registered on that date
425	     */
426	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
427	        return this.clinicService.findAllOwners().stream()
428	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
429	            .count();
430	    }
431	
432	    /**
433	     * Rejects an owner whose city already contains the maximum allowed number of owners
434	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
435	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
436	     * create.
437	     *
438	     * @param city the city of the owner being created
439	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
440	     */
441	    private void requireCityHasCapacity(String city) {
442	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
443	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
444	            .count();
445	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
446	            throw new CityOwnerLimitException(city);
447	        }
448	    }
449	
450	    /**
451	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
452	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
453	     * schema) that must fall within the inclusive range permitted for the region derived from the
454	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
455	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
456	     *
457	     * @param owner the owner being created, with its city and postcode set
458	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
459	     */
460	    private void validatePostcode(Owner owner) {
461	        String postcode = owner.getPostcode();
462	        if (postcode == null) {
463	            return;
464	        }
465	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
466	        if (range == null) {
467	            return;
468	        }
469	        int value = Integer.parseInt(postcode);
470	        if (value < range[0] || value > range[1]) {
471	            throw new InvalidOwnerFieldsException(List.of("postcode"));
472	        }
473	    }
474	
475	    /**
476	     * Counts the existing owners that already share the given first name and last name, compared
477	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
478	     * owners that existed prior to this create.
479	     *
480	     * @param firstName the first name of the owner being created
481	     * @param lastName the last name of the owner being created
482	     * @return the number of pre-existing namesakes
483	     */
484	    private int countNamesakes(String firstName, String lastName) {
485	        return (int) this.clinicService.findAllOwners().stream()
486	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
487	                && equalsIgnoreCase(existing.getLastName(), lastName))
488	            .count();
489	    }
490	
491	    /**
492	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
493	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
494	     *
495	     * @param a the first value, possibly {@code null}
496	     * @param b the second value, possibly {@code null}
497	     * @return whether the values are equal ignoring case
498	     */
499	    private boolean equalsIgnoreCase(String a, String b) {
500	        return a == null ? b == null : a.equalsIgnoreCase(b);
501	    }
502	
503	    /**
504	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
505	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
506	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
507	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
508	     *
509	     * @param ownerFieldsDto the submitted owner fields
510	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
511	     */
512	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
513	        List<String> invalidFields = new ArrayList<>();
514	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
515	            invalidFields.add("firstName");
516	        }
517	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
518	            invalidFields.add("lastName");
519	        }
520	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddressLine1()))
521	            && !StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
522	            invalidFields.add("address");
523	        }
524	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
525	            invalidFields.add("city");
526	        }
527	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
528	            invalidFields.add("telephone");
529	        }
530	        if (!invalidFields.isEmpty()) {
531	            throw new InvalidOwnerFieldsException(invalidFields);
532	        }
533	    }
534	
535	    /**
536	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
537	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
538	     * what gets stored and returned.
539	     *
540	     * @param telephone the raw telephone value from the request
541	     * @return the normalized E.164 telephone number
542	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
543	     */
544	    private String normalizeTelephone(String telephone) {
545	        String e164 = toE164(telephone);
546	        if (e164 == null) {
547	            throw new InvalidOwnerFieldsException(List.of("telephone"));
548	        }
549	        return e164;
550	    }
551	
552	    /**
553	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
554	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
555	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
556	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
557	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
558	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
559	     *
560	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
561	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
562	     *
563	     * @param telephone the raw telephone value, possibly {@code null}
564	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
565	     */
566	    private String toE164(String telephone) {
567	        if (telephone == null) {
568	            return null;
569	        }
570	        String cleaned = telephone.replaceAll("[ \\-()]", "");
571	        String digits;
572	        if (cleaned.startsWith("+")) {
573	            digits = cleaned.substring(1);
574	        } else {
575	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
576	            digits = "61" + national;
577	        }
578	        if (!digits.matches("[0-9]{8,15}")) {
579	            return null;
580	        }
581	        if (!nationalNumberLengthValid(digits)) {
582	            return null;
583	        }
584	        return "+" + digits;
585	    }
586	
587	    /**
588	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
589	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
590	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
591	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
592	     * accepted, leaving only the generic total-length rule to apply.
593	     *
594	     * @param digits the E.164 digits without the leading {@code '+'}
595	     * @return {@code true} if the national-number length matches the country code's requirement
596	     */
597	    private boolean nationalNumberLengthValid(String digits) {
598	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
599	            String code = entry.getKey();
600	            if (digits.startsWith(code)) {
601	                return digits.length() - code.length() == entry.getValue();
602	            }
603	        }
604	        return true;
605	    }
606	
607	    /**
608	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
609	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
610	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
611	     * returned lower-cased.
612	     *
613	     * @param email the raw email value from the request, possibly {@code null}
614	     * @return the lower-cased email, or {@code null} when none was supplied
615	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
616	     *     its domain is on the disposable-domain blocklist
617	     */
618	    private String normalizeEmail(String email) {
619	        if (!StringUtils.hasText(email)) {
620	            return null;
621	        }
622	        String trimmed = email.trim();
623	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
624	            throw new InvalidOwnerFieldsException(List.of("email"));
625	        }
626	        String normalized = trimmed.toLowerCase(Locale.ROOT);
627	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
628	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
629	            throw new InvalidOwnerFieldsException(List.of("email"));
630	        }
631	        return normalized;
632	    }
633	
634	    /**
635	     * Rejects an owner whose whole identity key is already used by an existing (non-deleted) owner.
636	     * This is the single consolidated duplicate check: the identity key
637	     * ({@link Owner#getIdentityKey()}) is the lower-case SHA-256 hex of the owner's normalized
638	     * telephone, lower-cased email (empty when absent) and the Soundex of its last name joined with
639	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
640	     * owner's. Because the telephone is part of the key, two owners sharing a last name and postcode
641	     * but carrying different telephones have different identity keys and are both allowed (the second
642	     * is flagged a soft match by {@link #flagPossibleDuplicate}). Owners flagged deleted are ignored.
643	     *
644	     * @param owner the owner being created, with its normalized telephone, email and last name set
645	     * @throws DuplicateIdentityException if another owner already has this identity key
646	     */
647	    private void requireUniqueIdentity(Owner owner) {
648	        String identityKey = owner.getIdentityKey();
649	        boolean inUse = this.clinicService.findAllOwners().stream()
650	            .filter(existing -> !existing.isDeleted())
651	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
652	        if (inUse) {
653	            throw new DuplicateIdentityException(identityKey);
654	        }
655	    }
656	
657	    /**
658	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
659	     * When the computed code is unique it is returned unchanged. When it collides with an existing
660	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
661	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
662	     * so on), and that de-duplicated code is returned.
663	     *
664	     * @param customerCode the freshly computed customer code to de-duplicate
665	     * @return a customer code not held by any existing owner
666	     */
667	    private String deduplicateCustomerCode(String customerCode) {
668	        Set<String> inUse = this.clinicService.findAllOwners().stream()
669	            .map(Owner::getCustomerCode)
670	            .filter(Objects::nonNull)
671	            .collect(Collectors.toSet());
672	        if (!inUse.contains(customerCode)) {
673	            return customerCode;
674	        }
675	        int n = 2;
676	        String candidate;
677	        do {
678	            candidate = customerCode + "-" + n;
679	            n++;
680	        } while (inUse.contains(candidate));
681	        return candidate;
682	    }
683	
684	    /**
685	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
686	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
687	     * but it shares an existing owner's last-name {@linkplain Soundex#encode(String) Soundex} and postcode
688	     * (both present and equal) while carrying a different identity key. When such an existing owner is
689	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
690	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
691	     * is false and {@code possibleDuplicateOf} is left unset.
692	     *
693	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
694	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
695	     *
696	     * @param owner the owner being created, with its normalized telephone, email, last name and postcode set
697	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
698	     */
699	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
700	        if (declaredHouseholdMember || owner.getPostcode() == null) {
701	            owner.setPossibleDuplicate(false);
702	            return;
703	        }
704	        String identityKey = owner.getIdentityKey();
705	        String soundex = Soundex.encode(owner.getLastName());
706	        Integer matchId = this.clinicService.findAllOwners().stream()
707	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName()))
708	                && owner.getPostcode().equals(existing.getPostcode())
709	                && !identityKey.equals(existing.getIdentityKey()))
710	            .map(Owner::getId)
711	            .min(Integer::compareTo)
712	            .orElse(null);
713	        owner.setPossibleDuplicate(matchId != null);
714	        owner.setPossibleDuplicateOf(matchId);
715	    }
716	
717	    /**
718	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
719	     * the household - the existing owners that share the deterministic {@code householdId} and the new
720	     * one - so the shared size can be read back from any of them. The count is the number of existing
721	     * members plus the owner being created.
722	     *
723	     * @param owner the owner being created, with its deterministic {@code householdId} already set
724	     */
725	    private void stampHouseholdSize(Owner owner) {
726	        List<Owner> members = householdMembers(owner);
727	        int householdSize = members.size() + 1;
728	        owner.setHouseholdSize(householdSize);
729	        for (Owner member : members) {
730	            member.setHouseholdSize(householdSize);
731	            this.clinicService.saveOwner(member);
732	        }
733	    }
734	
735	    /**
736	     * The existing owners that belong to the same household as the given owner - those that share its
737	     * deterministic {@code householdId}. This is the single definition of "who is in this household",
738	     * shared by the household-size stamp and the membership-level cap. The owner being created is not
739	     * among them (it has not been saved yet); soft-deleted owners are included, so callers that need
740	     * only live members filter them out themselves.
741	     *
742	     * @param owner the owner being created, with its deterministic {@code householdId} already set
743	     * @return the existing same-household owners
744	     */
745	    private List<Owner> householdMembers(Owner owner) {
746	        String householdId = owner.getHouseholdId();
747	        return this.clinicService.findAllOwners().stream()
748	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
749	            .toList();
750	    }
751	
752	    /**
753	     * Caps the new owner's membership level so it cannot exceed one above the current maximum
754	     * membership level among the existing members of its household - the non-deleted owners that share
755	     * the deterministic {@code householdId}. The new owner's level is lowered to that ceiling only when
756	     * its derived level sits above it; otherwise it is left to be derived normally. When the household
757	     * has no existing member no cap applies and the level is left untouched.
758	     *
759	     * @param owner the owner being created, with its deterministic {@code householdId} and
760	     *     {@code householdSize} already set
761	     */
762	    private void capMembershipLevelToHousehold(Owner owner) {
763	        OptionalInt maxMemberLevel = householdMembers(owner).stream()
764	            .filter(existing -> !existing.isDeleted())
765	            .mapToInt(Owner::getMembershipLevel)
766	            .max();
767	        if (maxMemberLevel.isEmpty()) {
768	            return;
769	        }
770	        int cap = maxMemberLevel.getAsInt() + 1;
771	        if (owner.getMembershipLevel() > cap) {
772	            owner.setMembershipLevel(cap);
773	        }
774	    }
775	
776	    /**
777	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
778	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
779	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
780	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
781	     * shares a last name and postcode computes the same identifier and therefore the same household.
782	     *
783	     * @param lastName the last name of the household
784	     * @param postcode the postcode of the household, possibly {@code null}
785	     * @return the 12-character upper-case hex household identifier
786	     */
787	    private String computeHouseholdId(String lastName, String postcode) {
788	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
789	        try {
790	            byte[] digest = MessageDigest.getInstance("SHA-256")
791	                .digest(key.getBytes(StandardCharsets.UTF_8));
792	            StringBuilder hex = new StringBuilder(12);
793	            for (int i = 0; i < 6; i++) {
794	                hex.append(String.format("%02X", digest[i]));
795	            }
796	            return hex.toString();
797	        } catch (NoSuchAlgorithmException e) {
798	            throw new IllegalStateException("SHA-256 algorithm not available", e);
799	        }
800	    }
801	
802	    /**
803	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
804	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
805	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
806	     *
807	     * @param value the raw value, possibly {@code null}
808	     * @return the normalized value
809	     */
810	    private String normalizeForHousehold(String value) {
811	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
812	    }
813	
814	    /**
815	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
816	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
817	     * value yields an empty string.
818	     *
819	     * @param value the raw value, possibly {@code null}
820	     * @return the trimmed, whitespace-collapsed value
821	     */
822	    private String collapseWhitespace(String value) {
823	        if (value == null) {
824	            return "";
825	        }
826	        return value.trim().replaceAll("\\s+", " ");
827	    }
828	
829	    /**
830	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
831	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
832	     * is upper-cased, and common street-type abbreviations are expanded as whole words
833	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
834	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
835	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
836	     *
837	     * @param address the raw address value, possibly {@code null}
838	     * @return the normalized address
839	     */
840	    private String normalizeAddress(String address) {
841	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
842	        if (collapsed.isEmpty()) {
843	            return "";
844	        }
845	        String[] tokens = collapsed.split(" ");
846	        StringBuilder normalized = new StringBuilder();
847	        for (int i = 0; i < tokens.length; i++) {
848	            if (i > 0) {
849	                normalized.append(' ');
850	            }
851	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
852	        }
853	        return normalized.toString();
854	    }
855	
856	    /**
857	     * Applies the owner's address from the request, preferring the structured form over the flat one.
858	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
859	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
860	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
861	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
862	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
863	     * the structured address when present, falling back to the flat address.
864	     *
865	     * @param owner the owner being created
866	     * @param ownerFieldsDto the submitted owner fields
867	     */
868	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
869	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
870	        if (StringUtils.hasText(line1)) {
871	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
872	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
873	            owner.setAddressLine1(line1);
874	            owner.setAddressLine2(normalizedLine2);
875	            owner.setAddress(composeAddress(line1, normalizedLine2));
876	        } else {
877	            owner.setAddressLine1(null);
878	            owner.setAddressLine2(null);
879	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
880	        }
881	    }
882	
883	    /**
884	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
885	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
886	     * appended when the second line is present.
887	     *
888	     * @param line1 the normalized first address line
889	     * @param line2 the normalized second address line, or {@code null} when absent
890	     * @return the composed address string
891	     */
892	    private String composeAddress(String line1, String line2) {
893	        return line2 == null ? line1 : line1 + " " + line2;
894	    }
895	
896	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
897	    @Override
898	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
899	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
900	        if (currentOwner == null) {
901	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
902	        }
903	        currentOwner.setAddress(ownerFieldsDto.getAddress());
904	        currentOwner.setCity(ownerFieldsDto.getCity());
905	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
906	        currentOwner.setLastName(ownerFieldsDto.getLastName());
907	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
908	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
909	        this.clinicService.saveOwner(currentOwner);
910	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
911	    }
912	
913	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
914	    @Transactional
915	    @Override
916	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
917	        Owner owner = this.clinicService.findOwnerById(ownerId);
918	        if (owner == null) {
919	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
920	        }
921	        owner.setDeleted(true);
922	        this.clinicService.saveOwner(owner);
923	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
924	    }
925	
926	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
927	    @Override
928	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
929	        Owner owner = this.clinicService.findOwnerById(ownerId);
930	        if (owner == null) {
931	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
932	        }
933	        HttpHeaders headers = new HttpHeaders();
934	        Pet pet = petMapper.toPet(petFieldsDto);
935	        owner.setId(ownerId);
936	        pet.setOwner(owner);
937	        pet.getType().setName(null);
938	        this.clinicService.savePet(pet);
939	        PetDto petDto = petMapper.toPetDto(pet);
940	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
941	            .buildAndExpand(pet.getId()).toUri());
942	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
943	    }
944	
945	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
946	    @Override
947	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
948	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
949	        if (currentOwner != null) {
950	            Pet currentPet = this.clinicService.findPetById(petId);
951	            if (currentPet != null) {
952	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
953	                currentPet.setName(petFieldsDto.getName());
954	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
955	                this.clinicService.savePet(currentPet);
956	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
957	            }
958	        }
959	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
960	    }
961	
962	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
963	    @Override
964	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
965	        HttpHeaders headers = new HttpHeaders();
966	        Visit visit = visitMapper.toVisit(visitFieldsDto);
967	        Pet pet = new Pet();
968	        pet.setId(petId);
969	        visit.setPet(pet);
970	        this.clinicService.saveVisit(visit);
971	        VisitDto visitDto = visitMapper.toVisitDto(visit);
972	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
973	            .buildAndExpand(visit.getId()).toUri());
974	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
975	    }
976	
977	
978	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
979	    @Override
980	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
981	        Owner owner = this.clinicService.findOwnerById(ownerId);
982	        if (owner != null) {
983	            Pet pet = owner.getPet(petId);
984	            if (pet != null) {
985	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
986	            }
987	        }
988	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
989	    }
990	}
